async function patchConnectionOverwrites(config, organizationName, solutionId, solutionDir, folder, fs) {
  const connectionsDir = fs.path.join(solutionDir, "resources", "solution_folder", "connection");
  if (!await fs.exists(connectionsDir)) {
    return 0;
  }
  const connectorDirs = await fs.readdir(connectionsDir);
  const connectionResources = (await Promise.all(connectorDirs.map(async (connectorDir) => {
    const connectorPath = fs.path.join(connectionsDir, connectorDir);
    const stat = await fs.stat(connectorPath);
    if (!stat.isDirectory())
      return [];
    const files = await fs.readdir(connectorPath);
    const results = await Promise.all(files.filter((file) => file.endsWith(".json")).map(async (file) => {
      const filePath = fs.path.join(connectorPath, file);
      const [readErr, content] = await catchError(fs.readFile(filePath, "utf-8"));
      if (readErr || !content)
        return;
      const [parseErr, parsed] = catchError(() => JSON.parse(content));
      if (parseErr || parsed.resource?.kind !== "connection")
        return;
      return parsed;
    }));
    return results.filter((r) => r !== undefined);
  }))).flat();
  if (connectionResources.length === 0) {
    return 0;
  }
  const tenantIdHeader = config.tenantId ? { "x-uipath-tenantid": config.tenantId } : {};
  const folderPath = folder.parentKey ? `${folder.parentKey}.${folder.key}` : folder.key;
  const folderPayload = {
    fullyQualifiedName: folder.fullyQualifiedName || folder.displayName,
    path: folderPath,
    folderKey: folder.key
  };
  const apiPath = `/resourcebuilder/solutions/${solutionId}/resources/reference?api-version=2&forceUpdate=true`;
  const validResources = connectionResources.filter((cr) => cr.resource.key && cr.resource.type);
  let successCount = 0;
  for (const cr of validResources) {
    const [err] = await catchError(studioWebPost(config, organizationName, apiPath, {
      kind: "connection",
      type: cr.resource.type,
      key: cr.resource.key,
      folder: folderPayload
    }, tenantIdHeader, "register-connection-resource"));
    if (err) {
      logger.warn(`Could not register connection resource ${cr.resource.key}: ${err.message}`);
      continue;
    }
    successCount++;
  }
  return successCount;
}

